# owner: platform
import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span
from hourglass.parsing import parse_span

OPEN = parse_span("09:00-17:00")

def spans(*texts):
    return [parse_span(text) for text in texts]

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = spans("09:00-12:00", "13:00-17:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_worked(self):
        self.assertEqual(
            find_gaps([], OPEN),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage(self):
        worked = spans("09:00-13:00", "12:00-17:00")
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_gaps_at_both_ends_and_between(self):
        worked = spans("10:00-11:00", "12:00-13:00")
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-12:00 (60 min)",
                "gap 13:00-17:00 (240 min)"
            ]
        )

    def test_overlap_leaves_no_false_gap(self):
        worked = [Span(540, 700), Span(600, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_span_starting_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("08:00-12:00"), OPEN)

    def test_span_ending_after_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(spans("16:00-18:00"), OPEN)

if __name__ == "__main__":
    unittest.main()
